<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('products.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
if($_SERVER['REQUEST_METHOD']==='POST'&&can('products.manage')){verify_csrf();$data=[trim($_POST['item_code']),trim($_POST['name']),($_POST['barcode']??'')?:null,($_POST['brand_id']??'')?:null,($_POST['category_id']??'')?:null,trim($_POST['model']??''),trim($_POST['unit']??'PCS')?:'PCS',(float)($_POST['avg_cost']??0),(float)$_POST['retail_price'],(float)$_POST['wholesale_price'],(float)($_POST['minimum_stock']??0),isset($_POST['serial_tracking'])?1:0,(int)($_POST['warranty_months']??0),trim($_POST['rack_location']??'')];try{$stmt=$db->prepare('INSERT INTO products(item_code,name,barcode,brand_id,category_id,model,unit,avg_cost,retail_price,wholesale_price,minimum_stock,serial_tracking,warranty_months,rack_location) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute($data);$id=(int)$db->lastInsertId();audit($db,'create','product',$id,null,$data);flash('success','Product added. Use Stock & Purchases to add quantity.');}catch(Throwable $e){flash('danger','Item code or barcode already exists. Please check and try again.');}redirect('products.php');}
$q=trim($_GET['q']??'');$like="%$q%";$stmt=$db->prepare('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status="active" AND (p.name LIKE ? OR p.item_code LIKE ? OR p.barcode LIKE ?) ORDER BY p.id DESC');$stmt->execute([$like,$like,$like]);$rows=$stmt->fetchAll();$brands=$db->query('SELECT * FROM brands WHERE status="active" ORDER BY name')->fetchAll();$categories=$db->query('SELECT * FROM categories WHERE status="active" ORDER BY name')->fetchAll();page_start('Products','products.php');?>
<style>.simple-fields{display:grid;gap:14px}.optional-fields{margin:18px 0;border:1px solid #e3e8e2;border-radius:10px;background:#f8faf7}.optional-fields summary{padding:13px 15px;cursor:pointer;font-weight:700;color:#174e39}.optional-fields[open] summary{border-bottom:1px solid #e3e8e2}.optional-fields .form-grid{padding:15px}</style><section class="action-banner"><div><span class="step-number">1</span><div><b>Add only the basic product information</b><p>Stock quantity and buying cost are normally added from Stock & Purchases.</p></div></div></section><div class="toolbar"><form><input name="q" value="<?=e($q)?>" placeholder="Search product"><button class="btn secondary">Search</button></form><?php if(can('products.manage')):?><button class="btn primary" onclick="document.getElementById('product-form').scrollIntoView({behavior:'smooth'})">+ Add Product</button><?php endif;?></div><div class="page-grid"><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Product list</span><h3><?=count($rows)?> products</h3></div></div><div class="table-wrap"><table><thead><tr><th>Code & Product</th><th>Category</th><th>In Stock</th><th>Retail Price</th><th>Wholesale Price</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5"><div class="empty-state compact"><b>No products yet</b><span>Use the simple form on the right.</span></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['item_code'])?></b><br><span class="muted"><?=e($r['name'])?></span></td><td><?=e($r['category']??'—')?></td><td><span class="status <?=$r['current_stock']<=$r['minimum_stock']?'overdue':'active'?>"><?=e($r['current_stock'])?> <?=e($r['unit'])?></span></td><td><?=money($r['retail_price'])?></td><td><?=money($r['wholesale_price'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php if(can('products.manage')):?><aside class="panel" id="product-form"><div class="panel-head"><div><span class="eyebrow">New product</span><h3>Add Product</h3></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><div class="simple-fields"><label>Item code<input name="item_code" placeholder="Example: TV-001" required></label><label>Product name<input name="name" placeholder="Example: Samsung 43 inch TV" required></label><label>Category<select name="category_id" required><option value="">Choose category</option><?php foreach($categories as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><label>Retail selling price<input type="number" step=".01" min="0" name="retail_price" required></label><label>Wholesale selling price<input type="number" step=".01" min="0" name="wholesale_price" required></label></div><details class="optional-fields"><summary>More details (optional)</summary><div class="form-grid"><label>Barcode<input name="barcode"></label><label>Brand<select name="brand_id"><option value="">Choose</option><?php foreach($brands as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><label>Model<input name="model"></label><label>Unit<input name="unit" value="PCS"></label><label>Opening cost<input type="number" step=".01" min="0" name="avg_cost" value="0"></label><label>Low-stock warning<input type="number" step=".001" min="0" name="minimum_stock" value="0"></label><label>Warranty months<input type="number" min="0" name="warranty_months" value="0"></label><label>Rack / location<input name="rack_location"></label><label class="full"><span><input type="checkbox" name="serial_tracking"> Track serial numbers</span></label></div></details><button class="btn primary wide">Save Product</button></form></aside><?php endif;?></div><?php page_end();

